/* Referência congelada da build 1.3.2 anterior a P1C.3B.3B.1; não modificar. */
function attack(e,melee=false){if(!canPlay())return;const p=G.hero;let range=melee?1:p.range;if(dist(p,e)>range||(!melee&&!lineClear(p.x,p.y,e.x,e.y))){log('O inimigo está fora do alcance ou atrás de uma parede.','!');beep(140);return;}stopAuto();aim=null;updateAim();const roll=window.GolzdovCombat.basicAttack(G,e,{predator:hasTalent('e_predador'),muralha:hasTalent('v_muralha')});if(roll.miss){log(`Você erra ${ENEMIES[e.type].name}.`,'⚔');beep(170,.08);}else{if(roll.consumeRiposte)p.riposte=0;heroHit(e,roll.damage,roll.critical?'ACERTO CRÍTICO':'Golpe','basic',roll.critical);beep(roll.critical?720:370,.095,'triangle');}worldTurn();updateHUD();save();}
function heroHit(e,damage,label,source='skill',critical=false){if(!e||e.hp<=0)return;const ctx=relicEvent('onAttack',{enemy:e,damage,kind:source,critical,wasSmoldering:(e.smolder||0)>0});hitEnemy(e,Math.max(1,Math.floor(ctx.damage)),label,source);}
function hitEnemy(e,dmg,kind,source='effect'){if(!e||e.hp<=0)return;e.hp-=dmg;log(`${kind}: ${ENEMIES[e.type].name} sofre ${dmg} de dano.`,'⚔');if(e.hp<=0)killEnemy(e,source);}
function receiveDamage(value,msg){let p=G.hero,damage=window.GolzdovCombat.incomingDamage(G,value,{muralha:hasTalent('v_muralha')});damage=relicEvent('onDefend',{damage}).damage;p.hp=Math.max(0,p.hp-damage);log(`${msg} −${damage} vida.`,'♥');beep(95,.15,'sawtooth');relicEvent('onHurt',{damage});if(p.hp<=0&&hasTalent('v_juramento')&&!p.lastOathUsed){p.hp=1;p.lastOathUsed=true;p.oathWeakened=true;log('Último Juramento: você resiste ao golpe fatal, mas sua guarda enfraquece.','◆');}else if(p.hp<=0)die();}
